FILE: CRM-Avance-Corp/supabase/scripts/f4/02-confirmacion.sql SHA256 6388b0ffb57431142eb97903c43cd9e1f3f22cc6ed23a01549dc27005f07f00a
1: create or replace function private.inversion_vincular_fuente(
2:   p_persona uuid,p_contrato uuid,p_cierre uuid,p_por uuid,p_inicial boolean default false)
3: returns uuid language plpgsql security definer set search_path='' as $$
4: declare
5:   v_empresa uuid;
6:   v_fecha date;
7:   v_estado text;
8:   v_identidad uuid;
9:   v_i crm.inversiones%rowtype;
10: begin
11:   if ((p_contrato is not null)::integer+(p_cierre is not null)::integer)<>1 then
12:     raise exception 'La inversión requiere exactamente una fuente económica' using errcode='22023';
13:   end if;
14:   if p_cierre is not null then
15:     select e.id,coalesce(ce.fecha_comercial,(ce.creado_en at time zone 'America/Lima')::date),
16:       case when ce.anulado_en is null then 'vigente' else 'anulada' end,
17:       private.inversionista_canonica(ce.inversionista_id)
18:     into v_empresa,v_fecha,v_estado,v_identidad
19:     from crm.cierres_externos ce join crm.empresas e on e.clave=ce.cooperativa
20:     where ce.id=p_cierre for share of ce;
21:   else
22:     select e.id,c.fecha_cierre_comercial,'vigente',private.inversionista_canonica(p.id)
23:     into v_empresa,v_fecha,v_estado,v_identidad
24:     from public.contratos c join crm.inversionistas p on p.perfil_id=c.cliente_id and p.estado<>'fusionado'
25:     cross join crm.empresas e where c.id=p_contrato and e.clave='avance' for share of c;
26:   end if;
27:   if v_empresa is null or v_identidad is distinct from p_persona then
28:     raise exception 'La fuente económica no corresponde a esta persona' using errcode='P0409';
29:   end if;
30:   -- También protege una vinculación histórica: si el borrado se preparó antes
31:   -- de obtener el candado contractual, no añadir una relación a esa fuente.
32:   if p_contrato is not null and private.contrato_en_eliminacion(p_contrato) then
33:     raise exception 'El contrato está en proceso de eliminación; requiere revisión' using errcode='55000';
34:   end if;
35:   select * into v_i from crm.inversiones
36:   where contrato_id=p_contrato or cierre_externo_id=p_cierre for update;
37:   if found then
38:     if v_i.inversionista_id<>p_persona or v_i.empresa_id<>v_empresa then
39:       raise exception 'La fuente ya está vinculada a otra persona o empresa' using errcode='P0409';
40:     end if;
41:   else
42:     insert into crm.inversiones(inversionista_id,empresa_id,contrato_id,cierre_externo_id,
43:       estado,fecha_comercial,es_primera_conversion,creado_por)
44:     values(p_persona,v_empresa,p_contrato,p_cierre,v_estado,v_fecha,p_inicial,p_por)
45:     returning * into v_i;
46:   end if;
47:   if exists (select 1 from crm.inversion_titulares it
48:              where it.inversion_id=v_i.id and it.rol='principal' and it.inversionista_id<>p_persona) then
49:     raise exception 'El titular principal requiere conciliación' using errcode='P0409';
50:   end if;
51:   insert into crm.inversion_titulares(inversion_id,inversionista_id,rol,creado_por)
52:   select v_i.id,p_persona,'principal',p_por where not exists (
53:     select 1 from crm.inversion_titulares it where it.inversion_id=v_i.id and it.rol='principal');
54:   return v_i.id;
55: end;
56: $$;
