60: create or replace function crm.confirmar_inversion_fn(p_solicitud uuid)
61: returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
62: declare
63:   v_uid uuid := (select auth.uid());
64:   v_persona uuid;
65:   v_origen uuid;
66:   v_ctx jsonb;
67:   v_s crm.inversion_solicitudes%rowtype;
68:   v_e crm.empresas%rowtype;
69:   v_obj storage.objects%rowtype;
70:   v_cierre uuid;
71:   v_contrato uuid;
72:   v_inversion uuid;
73:   v_fecha date;
74:   v_imputacion date;
75:   v_periodo date;
76:   v_ahora timestamptz := statement_timestamp();
77:   v_ajuste boolean := false;
78:   v_fuente jsonb;
79:   v_payload_contrato jsonb;
80:   v_condicion uuid;
81:   v_config_producto text := current_setting('crm.producto_condicion_id',true);
82:   v_responsable_inicial uuid;
83:   v_res jsonb;
84: begin
85:   if v_uid is null or not private.puede_gestionar_contratos_crm() then
86:     raise exception 'No autorizado para registrar inversiones' using errcode='42501';
87:   end if;
88:   select inversionista_id into v_persona from crm.inversion_solicitudes where id=p_solicitud;
89:   if not found then raise exception 'Solicitud no encontrada' using errcode='P0002'; end if;
90:   v_origen := v_persona;
91:   v_ctx := private.inversion_persona_autorizada(v_persona);
92:   v_persona := (v_ctx->>'inversionista_id')::uuid;
93:   select * into v_s from crm.inversion_solicitudes where id=p_solicitud for update;
94:   if not found or v_s.inversionista_id is distinct from v_origen then
95:     raise exception 'La solicitud cambió; vuelve a cargarla' using errcode='40001';
96:   end if;
97:   if v_s.estado='confirmada' then
98:     v_res:=v_s.resultado;
99:     select contrato_id into v_contrato from crm.inversiones where id=v_s.inversion_id;
100:     if v_contrato is not null then
101:       if private.contrato_en_eliminacion(v_contrato) then
102:         raise exception 'El contrato está en proceso de eliminación; requiere revisión' using errcode='55000';
103:       end if;
104:       v_res:=jsonb_set(v_res,'{fuente,pdf}',private.contrato_pdf_estado_base(v_contrato));
105:     end if;
106:     return v_res||jsonb_build_object('inversionista_id',v_persona,'reintento',true);
107:   end if;
108:   if v_s.estado<>'preparada' then raise exception 'La solicitud está cancelada' using errcode='P0409'; end if;
109:   v_ctx := private.inversion_persona_contexto(v_persona);
110:   if v_s.responsable_esperado_id is distinct from (v_ctx->>'responsable_id')::uuid then
111:     raise exception 'El responsable cambió; revisa esta misma solicitud antes de confirmarla' using errcode='P0409';
112:   end if;
113:   select * into v_e from crm.empresas where id=v_s.empresa_id and activa for share;
114:   if not found then raise exception 'La empresa ya no está disponible para nuevas inversiones' using errcode='P0409'; end if;
115:   if v_e.fuente_capital='cierres_externos' then
116:     if v_s.datos->>'moneda' is distinct from 'PEN' or not ('PEN'=any(v_e.monedas)) then
117:       raise exception 'La moneda ya no está admitida por la cooperativa' using errcode='P0409';
118:     end if;
119:     select * into v_obj from storage.objects
120:     where bucket_id='f4-comprobantes' and name=v_s.datos#>>'{evidencia,ruta}' for key share;
121:     if not found or coalesce((v_obj.metadata->>'size')::bigint,0) not between 1 and 10485760
122:        or coalesce(v_obj.metadata->>'mimetype','') not in ('application/pdf','image/jpeg','image/png') then
123:       raise exception 'Sube el comprobante válido antes de confirmar la inversión' using errcode='P0409';
124:     end if;
125:     v_fecha := (v_s.datos->>'fecha_comercial')::date;
126:     v_periodo := date_trunc('month',v_fecha)::date;
127:     -- Mismo candado que el sello mensual. El sello no puede aparecer entre la
128:     -- decisión y el alta. Un mes sellado recibe un hecho posterior trazable.
129:     perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('crm.periodos_cerrados'),
130:       (v_periodo-date '2000-01-01')::integer);
131:     v_ajuste := exists(select 1 from crm.periodos_cerrados where periodo=v_periodo);
132:     v_imputacion := case when v_ajuste then (v_ahora at time zone 'America/Lima')::date else v_fecha end;
133:     if v_ajuste then
134:       perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('crm.periodos_cerrados'),
135:         (date_trunc('month',v_imputacion)::date-date '2000-01-01')::integer);
136:       if exists(select 1 from crm.periodos_cerrados where periodo=date_trunc('month',v_imputacion)::date) then
137:         raise exception 'El período de registro también está sellado; corresponde revisión de Gerencia' using errcode='P0409';
138:       end if;
139:     end if;
140:     begin
141:       insert into crm.cierres_externos(lead_id,cooperativa,monto,moneda,documento_tipo,documento,
142:         nombre_completo,numero_transaccion,referencia_externa,vence_en,vendedor_id,creado_por,
143:         inversionista_id,creado_en,es_cierre_inicial,fecha_comercial,fecha_imputacion,comprobante_objeto_id)
144:       values((v_ctx->>'lead_id')::uuid,v_e.clave,(v_s.datos->>'monto')::numeric,'PEN',
145:         v_ctx->>'documento_tipo',v_ctx->>'documento',v_ctx->>'nombre',
146:         upper(btrim(v_s.datos->>'numero_transaccion')),btrim(v_s.datos->>'referencia'),
147:         (v_s.datos->>'vence_en')::date,(v_ctx->>'responsable_id')::uuid,v_uid,v_persona,
148:         v_ahora,false,v_fecha,v_imputacion,v_obj.id) returning id into v_cierre;
149:       -- La reclamación histórica del depósito es global para ambas cooperativas.
150:       insert into crm.depositos_reclamados(numero_norm,cierre_id,reclamado_por)
151:       values(upper(btrim(v_s.datos->>'numero_transaccion')),v_cierre,v_uid);
152:     exception when unique_violation then
153:       raise exception 'Ese número de operación del depósito ya está registrado' using errcode='P0409';
154:     end;
155:     v_fuente:=jsonb_build_object('cierre_id',v_cierre,'fecha_comercial',v_fecha,
156:       'fecha_imputacion',v_imputacion,'ajuste_mes_cerrado',v_ajuste);
157:   elsif v_e.clave='avance' then
158:     if v_ctx->>'perfil_id' is null then
159:       raise exception 'Completa el acceso Avance de esta persona y vuelve a confirmar la misma solicitud' using errcode='P0409';
160:     end if;
161:     v_payload_contrato := v_s.datos->'contrato';
162:     select r.responsable_anterior_id into v_responsable_inicial
163:       from crm.inversion_solicitud_revisiones r where r.solicitud_id=v_s.id order by r.revision limit 1;
164:     v_responsable_inicial:=coalesce(v_responsable_inicial,v_s.responsable_esperado_id);
165:     if v_payload_contrato->>'cliente_id' is not null
166:        and v_payload_contrato->>'cliente_id' is distinct from v_ctx->>'perfil_id' then
167:       raise exception 'El contrato no corresponde a esta persona' using errcode='P0409';
168:     end if;
169:     if v_payload_contrato->>'analista_cierre_id' is not null
170:        and v_payload_contrato->>'analista_cierre_id' is distinct from v_responsable_inicial::text then
171:       raise exception 'El analista del contenido original no corresponde al responsable con que se preparó la inversión' using errcode='P0409';
172:     end if;
173:     -- El contenido original conserva su huella. Una revisión explícita cambia
174:     -- el responsable con quien se confirma, sin reescribir las condiciones.
175:     v_payload_contrato := v_payload_contrato||jsonb_build_object('cliente_id',v_ctx->>'perfil_id',
176:       'analista_cierre_id',v_ctx->>'responsable_id');
177:     -- La fuente existente conserva producto, tasa, cronograma, cuenta, titularidad
178:     -- documental y operaciones de cartera. Todo participa de esta transacción.
179:     -- Reutiliza además la reserva y el snapshot documentales del alta publicada.
180:     -- Un PDF pendiente no vuelve a crear el contrato cuando se recupera el envío.
181:     -- El flujo Avance vigente es libre y fotografía sus términos. El catálogo
182:     -- sigue siendo opcional: F4 no lo convierte en un requisito comercial nuevo.
183:     perform pg_catalog.set_config('crm.producto_condicion_id',
184:       coalesce((nullif(v_s.datos->>'producto_condicion_id','')::uuid)::text,''),true);
185:     begin
186:       v_fuente := crm.crear_contrato_con_cuenta_pdf_v2(
187:         v_payload_contrato||jsonb_build_object('clave_idempotencia',v_s.id),
188:         v_s.datos->'cronograma',v_s.datos->'cuenta');
189:     exception when others then
190:       perform pg_catalog.set_config('crm.producto_condicion_id',coalesce(v_config_producto,''),true);
191:       raise;
192:     end;
193:     perform pg_catalog.set_config('crm.producto_condicion_id',coalesce(v_config_producto,''),true);
194:     v_contrato := (v_fuente->>'id')::uuid;
195:     if v_contrato is null then raise exception 'El contrato no devolvió su identificador' using errcode='P0001'; end if;
196:     select producto_condicion_id into v_condicion from public.contratos where id=v_contrato;
197:     v_fuente:=v_fuente||private.metadata_condicion_producto(v_condicion);
198:   else
199:     raise exception 'Empresa sin puerta de inversión disponible' using errcode='P0409';
200:   end if;
201:   v_inversion := private.inversion_vincular_fuente(v_persona,v_contrato,v_cierre,v_uid,false);
202:   if v_ajuste then
203:     insert into crm.inversion_ajustes_mes_cerrado(inversion_id,periodo_origen,fecha_imputacion,creado_por)
204:     values(v_inversion,v_periodo,v_imputacion,v_uid);
205:   end if;
206:   insert into crm.inversion_eventos(inversion_id,tipo,creado_por) values(v_inversion,'registro',v_uid);
207:   v_res := jsonb_build_object('ok',true,'solicitud_id',v_s.id,'inversion_id',v_inversion,
208:     'inversionista_id',v_persona,'lead_id',v_ctx->>'lead_id','empresa',v_e.clave,'fuente',v_fuente);
209:   update crm.inversion_solicitudes set estado='confirmada',inversion_id=v_inversion,
210:     resultado=v_res,confirmado_por=v_uid,actualizado_en=statement_timestamp() where id=v_s.id;
211:   return v_res;
212: end;
213: $$;
