1: // Copia exclusivamente la base sintética F4 para ensayos SQL entre sesiones.
2: // No copia archivos de Storage ni representa un ensayo HTTP/Auth independiente.
3: import assert from 'node:assert/strict';
4: import { spawn, spawnSync } from 'node:child_process';
5: import { mkdirSync, openSync, closeSync } from 'node:fs';
6: import { randomUUID } from 'node:crypto';
7: import { join } from 'node:path';
8: import { banco, contenedor, literal } from './banco-local.mjs';
9: 
10: export function crearCopiaSql(etiqueta) {
11:   assert(/^[a-z_]{1,24}$/.test(etiqueta));
12:   const id = randomUUID();
13:   const nombre = `f4_${etiqueta}_${id.replaceAll('-', '').slice(0,12)}`;
14:   const carpeta = join(banco, 'copias-sql', nombre);
15:   mkdirSync(carpeta, { recursive: true, mode: 0o700 });
16:   function ejecutar(args, opciones = {}) {
17:     const r = spawnSync('docker', ['exec', '-i', contenedor, ...args],
18:       { encoding: 'utf8', maxBuffer: 16 * 1024 * 1024, ...opciones });
19:     assert.equal(r.status, 0, r.stderr || r.error?.message || `Falló ${args[0]}`);
20:     return r.stdout?.trim();
21:   }
22:   const archivo = join(carpeta, 'base-sintetica.dump');
23:   const fd = openSync(archivo, 'wx', 0o600);
24:   try {
25:     // pg_cron solo puede instalarse en la base del planificador; sus tareas y
26:     // replicación no forman parte de este ensayo y no deben arrancar duplicadas.
27:     ejecutar(['pg_dump','-U','supabase_admin','-d','postgres','-Fc',
28:       '--exclude-extension=pg_cron','--exclude-schema=cron','--no-publications','--no-subscriptions'],
29:     { stdio: ['ignore',fd,'pipe'] });
30:   } finally { closeSync(fd); }
31:   ejecutar(['createdb','-U','supabase_admin',nombre]);
32:   const entrada = openSync(archivo, 'r');
33:   try {
34:     ejecutar(['pg_restore','-U','supabase_admin','-d',nombre,'--exit-on-error'],
35:       { stdio: [entrada,'pipe','pipe'] });
36:   } finally { closeSync(entrada); }
37: 
38:   function sql(texto) {
39:     return ejecutar(['psql','-X','-qAt','-U','postgres','-d',nombre,
40:       '-v','ON_ERROR_STOP=1','-f','-'], { input: `set timezone='America/Lima';\n${texto}\n` });
41:   }
42:   function abrirSesion(aplicacion) {
43:     assert(/^[a-z0-9_-]{1,60}$/.test(aplicacion));
44:     const p = spawn('docker', ['exec','-i',contenedor,'psql','-X','-qAt','-U','postgres',
45:       '-d',nombre,'-v','ON_ERROR_STOP=1','-f','-'], { stdio: ['pipe','pipe','pipe'] });
46:     let salida = '', error = '';
47:     p.stdout.setEncoding('utf8'); p.stderr.setEncoding('utf8');
48:     p.stdout.on('data', s => { salida += s; });
49:     p.stderr.on('data', s => { error += s; });
50:     // El resultado nunca rechaza antes de que el controlador pueda observarlo.
51:     const terminado = new Promise(resolve => {
52:       p.on('error', e => resolve({ codigo: -1, salida, error: e.message }));
53:       p.on('close', codigo => resolve({ codigo, salida: salida.trim(), error }));
54:     });
55:     p.stdin.on('error', () => {});
56:     p.stdin.write(`set application_name=${literal(aplicacion)}; set timezone='America/Lima';\n`);
57:     return { enviar: texto => p.stdin.write(`${texto}\n`),
58:       cerrar: (texto = 'rollback;') => { p.stdin.end(`${texto}\n`); return terminado; },
59:       terminado, salida: () => salida };
60:   }
61:   async function esperar(predicado, mensaje, plazo = 4500) {
62:     const hasta = Date.now() + plazo;
63:     while (Date.now() < hasta) {
64:       if (predicado()) return;
65:       await new Promise(resolve => setTimeout(resolve, 40));
66:     }
67:     assert.fail(mensaje);
68:   }
69:   return { id, nombre, carpeta, archivo, sql, abrirSesion, esperar };
70: }
